#!/usr/bin/env python3
# Stateful 2FA mock (stdlib). Login flow: GET /login -> POST /login -> GET /login2 -> POST /login2.
# session id and csrf token rotate per stage; 2 wrong OTPs invalidate the session (must re-auth).
import http.server, socketserver, secrets, re, os, sys, threading, urllib.parse
USER, PASS = "carlos", "montoya"
CODE = f"{secrets.randbelow(10000):04d}"   # generated in-memory; never in args/env/disk
SESS = {}   # sid -> {stage, csrf, wrong}
def new_sid():
    s = secrets.token_hex(8); SESS[s] = {"stage": "creds", "csrf": secrets.token_hex(8), "wrong": 0}
    return s
class H(http.server.BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def _sid(self):
        c = self.headers.get("Cookie", "")
        m = re.search(r"session=([0-9a-f]+)", c)
        return m.group(1) if m and m.group(1) in SESS else None
    def _send(self, body, sid=None, code=200, loc=None):
        self.send_response(code)
        if sid: self.send_header("Set-Cookie", f"session={sid}; Path=/")
        if loc: self.send_header("Location", loc)
        self.send_header("Content-Type", "text/html"); self.end_headers()
        self.wfile.write(body.encode())
    def do_GET(self):
        if self.path == "/login":
            sid = new_sid(); st = SESS[sid]
            self._send(f'<form><input name="username"><input name="password"><input name="csrf" value="{st["csrf"]}"></form>', sid=sid)
        elif self.path == "/login2":
            sid = self._sid()
            if not sid or SESS[sid]["stage"] != "otp": self._send("go to /login", code=400); return
            st = SESS[sid]
            self._send(f'<p>Please enter 4-digit code</p><form><input name="mfa-code"><input name="csrf" value="{st["csrf"]}"></form>')
        elif self.path == "/my-account":
            sid = self._sid()
            if sid and SESS[sid]["stage"] == "done": self._send("Welcome carlos"); 
            else: self._send("unauthorized", code=401)
        else: self._send("nf", code=404)
    def do_POST(self):
        n = int(self.headers.get("Content-Length", 0)); body = self.rfile.read(n).decode()
        form = {k: v[0] for k, v in urllib.parse.parse_qs(body).items()}
        sid = self._sid()
        if self.path == "/login":
            if not sid: self._send("no session", code=400); return
            st = SESS[sid]
            if st["stage"] != "creds" or form.get("csrf") != st["csrf"]: self._send("bad csrf/stage", code=400); return
            if form.get("username") == USER and form.get("password") == PASS:
                # rotate session + csrf, advance to otp
                del SESS[sid]; nsid = secrets.token_hex(8)
                SESS[nsid] = {"stage": "otp", "csrf": secrets.token_hex(8), "wrong": 0}
                self._send("", sid=nsid, code=302, loc="/login2")
            else: self._send("invalid creds", code=200)
        elif self.path == "/login2":
            if not sid or SESS[sid]["stage"] != "otp": self._send("go to /login", code=400); return
            st = SESS[sid]
            if form.get("csrf") != st["csrf"]: self._send("bad csrf", code=400); return
            if form.get("mfa-code") == CODE:
                st["stage"] = "done"; self._send("", code=302, loc="/my-account")
            else:
                st["wrong"] += 1
                if st["wrong"] >= 2:
                    del SESS[sid]; self._send("Incorrect security code - session invalidated", code=200)
                else:
                    st["csrf"] = secrets.token_hex(8)   # rotate csrf even on wrong try
                    self._send("Incorrect security code", code=200)
        else: self._send("nf", code=404)
if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    httpd = socketserver.TCPServer(("127.0.0.1", port), H)
    with open(os.path.join(os.path.dirname(__file__), "port.txt"), "w") as f: f.write(str(httpd.server_address[1]))
    httpd.serve_forever()

SRVEOF
